solution.exercise.cpp:
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
bool territory(const char*const*b,size_t rows,size_t x,size_t y,char*owner,point*out,size_t*count){*count=0;*owner=0;if(y>=rows||x>=strlen(b[y]))return false;size_t cols=strlen(b[0]);if(b[y][x]=='B'||b[y][x]=='W')return true;bool*v=(bool*)calloc(rows*cols,sizeof(bool));size_t head=0,tail=0;out[tail++]=(point){x,y};v[y*cols+x]=true;unsigned borders=0;while(head<tail){point p=out[head++];long dx[]={0,0,1,-1},dy[]={1,-1,0,0};for(int k=0;k<4;k++){long xx=(long)p.x+dx[k],yy=(long)p.y+dy[k];if(xx<0||yy<0||(size_t)yy>=rows||(size_t)xx>=cols)continue;char c=b[yy][xx];if(c=='B')borders|=1;else if(c=='W')borders|=2;else if(!v[yy*cols+xx]){v[yy*cols+xx]=true;out[tail++]=(point){(size_t)xx,(size_t)yy};}}}*count=tail;*owner=borders==1?'B':borders==2?'W':0;free(v);return true;}void territories(const char*const*b,size_t rows,char*owners){if(!rows)return;size_t cols=strlen(b[0]);bool*v=(bool*)calloc(rows*cols,sizeof(bool));point*p=(point*)malloc(rows*cols*sizeof(point));memset(owners,0,rows*cols);for(size_t y=0;y<rows;y++)for(size_t x=0;x<cols;x++)if(!v[y*cols+x]){char owner;size_t n;territory(b,rows,x,y,&owner,p,&n);for(size_t i=0;i<n;i++){v[p[i].y*cols+p[i].x]=true;owners[p[i].y*cols+p[i].x]=owner;}}free(v);free(p);}

