#include "exercise.h"
#include <assert.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>
#include <stdio.h>
static bool positive(int x){return x>0;}
static bool bstring(const void*p){return (*(const char*const*)p)[0]==98;}
static void string_length(const void*p,void*out){*(size_t*)out=strlen(*(const char*const*)p);}
int main(void){
const char*b[]={"BBB","B B","BBB"};point p[9];size_t n;char owner,o[9];assert(territory(b,3,1,1,&owner,p,&n)&&owner=='B'&&n==1);assert(territory(b,3,0,0,&owner,p,&n)&&owner==0&&n==0);assert(!territory(b,3,3,0,&owner,p,&n));territories(b,3,o);assert(o[4]=='B');const char*m[]={"B W","   "};assert(territory(m,2,1,0,&owner,p,&n)&&owner==0&&n==4);

return 0;}
